mapper.sql:
where a.patient_id = #{patientId}
  and a.tenant_id = #{tenantId}

    and a.status = #{status}


    and a.reg_date >= #{beginDate}


    and a.reg_date <= #{endDate}

mapper.select:
select id, patient_id, doctor_id, reg_date, time_range, status, fee, tenant_id
from appointment
where id = #{id}
  and tenant_id = #{tenantId}

mapper.update:
update appointment
set status = #{status}
where id = #{id}

update appointment
set reg_date   = #{regDate},
    time_range = #{timeRange}
where id = #{id}

mapper.select:
select count(*)
from appointment
where doctor_id = #{doctorId}
  and reg_date = #{regDate}
  and time_range = #{timeRange}
  and status <> 'CANCELLED'
